$_MODULE['<{vatnumber}prestashop>intro_4cd91094c199d113383602668f77405e'] = 'Partite IVA respinte';
$_MODULE['<{vatnumber}prestashop>intro_e29d8c976dabe0f74f1516a02ffddb4d'] = 'Questi numeri sono stati respinti da VIES o non possono esistere per il loro formato. Un numero cosi non ottiene mai l\'esenzione IVA. Cliente e ultimo ordine appartengono all\'indirizzo su cui il numero e stato visto per l\'ultima volta.';
$_MODULE['<{vatnumber}prestashop>intro_c45d25c3d382ec4f3be5371fa47694ee'] = 'Cosa fare: chiedete al cliente il numero corretto. Se con questo numero e stato effettuato un ordine senza IVA, controllatelo e rifatturate l\'IVA se necessario. Un numero corretto dal cliente viene verificato di nuovo automaticamente.';
$_MODULE['<{vatnumber}prestashop>intro_eee81301e59ec7f49d779ad15273ef04'] = 'I numeri respinti vengono rimossi automaticamente dagli indirizzi dei clienti (impostazione nella scheda Impostazioni).';
$_MODULE['<{vatnumber}prestashop>intro_39d2c6171b29dfb08bbca6ab2861440d'] = 'I numeri respinti restano sugli indirizzi dei clienti. Nella scheda Impostazioni potete farli rimuovere automaticamente.';
$_MODULE['<{vatnumber}prestashop>vatnumber_fd7933d29ee75710500907bb51616f37'] = 'Numeri respinti (%d)';
$_MODULE['<{vatnumber}prestashop>vatnumber_c168294e867ffbd1b55009c5166e2abd'] = 'Verificare anche i numeri del proprio paese';
$_MODULE['<{vatnumber}prestashop>vatnumber_29ba70bd28bf912c9c5972e421824ed0'] = 'I clienti del vostro paese pagano sempre l\'IVA, quindi normalmente del loro numero si verifica solo il formato. Attivatelo per far confermare anche questi numeri da VIES, cosi un numero inesistente non puo essere salvato.';
$_MODULE['<{vatnumber}prestashop>vatnumber_516390087ffcfb67655ef69db2decf35'] = 'Utile quando le partite IVA vengono passate alla contabilita o a un altro sistema che rifiuta i numeri sconosciuti. L\'attivita pianificata verifica comunque i numeri nazionali salvati.';
$_MODULE['<{vatnumber}prestashop>vatnumber_ae99eed504a1c929083b3c2fb2d7efc0'] = 'Rimuovere i numeri respinti dagli indirizzi';
$_MODULE['<{vatnumber}prestashop>vatnumber_4204f91300a46cc20b1df728455afdfc'] = 'Quando VIES respinge una partita IVA, viene rimossa dagli indirizzi dei clienti che la riportano, cosi non arriva piu nelle fatture e nella contabilita. Ogni rimozione viene scritta nel log del negozio.';
$_MODULE['<{vatnumber}prestashop>vatnumber_96c0952eece4b01740f11939a945a403'] = 'Vale per i rifiuti dell\'attivita pianificata e della verifica manuale qui sotto. Gli ordini gia effettuati mantengono il loro indirizzo invariato: un indirizzo usato negli ordini viene sostituito da una copia senza numero, quello vecchio resta collegato a quegli ordini.';
$_MODULE['<{vatnumber}prestashop>vatnumber_4d692c4d3c6e343264d479d43baccf93'] = 'Il numero e stato rimosso da %d indirizzo/i cliente, vedere il log del negozio.';
